// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzing a single address input (arbitrary caller) to exercise the notDelegated modifier context
    function testFuzz_property(address caller) public {
        // Keep the domain wide but avoid the zero address for a more meaningful caller
        vm.assume(caller != address(0));

        // We'll call proxiableUUID via an external call from the fuzzed caller using vm.prank.
        // The reference returns IMPLEMENTATION_SLOT; the mutant would return ADMIN_SLOT for some runs.
        bytes32 ret;
        vm.prank(caller);
        try c.proxiableUUID() returns (bytes32 r) {
            ret = r;
        } catch {
            // If it reverts for this caller, treat as a distinct behavior; set ret to zero sentinel
            ret = bytes32(0);
        }

        // The universal property: the reference C always returns ERC1967Utils.IMPLEMENTATION_SLOT when callable.
        // We assert that the returned slot equals the expected IMPLEMENTATION_SLOT constant value as observed
        // via calling proxiableUUID from this caller. This will hold for the reference and fail for the mutant
        // on inputs where the mutant returns ADMIN_SLOT instead.
        // We obtain the expected implementation slot by calling proxiableUUID from the contract itself
        // (no prank) to read the canonical value; this read must succeed on the reference.
        bytes32 canonical;
        try c.proxiableUUID() returns (bytes32 r2) {
            canonical = r2;
        } catch {
            canonical = bytes32(0);
        }

        // Exactly one assertion: the value observed when called by the fuzzed caller equals the canonical
        // proxiableUUID() value observed from the default (test) caller context.
        assertTrue(ret == canonical);
    }
}

