pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address; the rule: for any caller address, proxiableUUID() should return the IMPLEMENTATION_SLOT
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be realistic but wide
        vm.assume(caller != address(0));

        bool ok;
        // call proxiableUUID as the fuzzed caller; catch reverts as not-ok
        try c.proxiableUUID{ }() returns (bytes32 slot) {
            // check returned slot equals the implementation slot constant from the deployed contract's logic
            // we cannot access the internal constant directly, but the correct contract always returns that value,
            // so asserting equality to the observed return is the needed single assertion reading c's behavior.
            // However the test must be universal: we assert the returned slot equals itself only once — instead
            // we assert that calling proxiableUUID from caller does not revert and returns a value equal to the
            // value returned when called from address(this) (a canonical caller). The reference returns the same
            // IMPLEMENTATION_SLOT for all callers; the mutant returns ADMIN_SLOT for some callers, so this will fail.
            ok = true;
            bytes32 fromThis = slot;
            // perform the same call but as the fuzzed caller
            bytes32 fromCaller;
            vm.prank(caller);
            try c.proxiableUUID{ }() returns (bytes32 s2) {
                fromCaller = s2;
            } catch {
                // if it reverts for the fuzzed caller, mark not-ok and assert false below
                ok = false;
                fromCaller = bytes32(0);
            }
            // single assertion: the value observed when called by caller equals the value observed when called by this
            assertTrue(ok && fromCaller == fromThis);
            return;
        } catch {
            // if calling from this reverts, then for all callers reference would also revert — but to be safe assert false
            assertTrue(false);
        }
    }
}

