import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // keep caller as any address (wide domain). We need a caller that is NOT the contract itself
        // because the notDelegated modifier reverts when called via delegatecall; calling externally is fine.
        // ensure caller is not address(0) to be in reasonable domain
        vm.assume(caller != address(0));

        bool ok;
        // call proxiableUUID from the fuzzed caller context
        vm.prank(caller);
        try c.proxiableUUID() returns (bytes32 slot) {
            // if call succeeded, check it equals the IMPLEMENTATION_SLOT constant
            // We cannot reference ERC1967Utils here, but we know the reference implementation returns that constant value.
            // Read back via the call result 'slot'. The universal property: slot == c.proxiableUUID() == IMPLEMENTATION_SLOT
            // We assert that the call succeeded (ok) and slot equals the expected IMPLEMENTATION_SLOT bytes32 literal
            // To obtain the expected constant value, invoke the function again (from same context) and compare to itself.
            // Actually we need a single assertTrue reading c: assert that the returned slot equals the value returned when called by any other caller (here address(this)).
            ok = (slot == c.proxiableUUID());
        } catch {
            ok = false;
        }

        // single assertion: for the reference contract, calling proxiableUUID from any caller returns the same bytes32 as calling it from this test contract; the mutant returns a different constant for some caller and will break this.
        assertTrue(ok);
    }
}

