pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz a random address to pass as _accessControl (keeps it wide);
    // the difference is initialization of UUPS internals, independent of the exact address,
    // so the fuzzer can supply any address (including zero).
    function testFuzz_property(address accessControl) public {
        // allow any address (wide domain); no assumptions required

        // call initialize and observe whether calling proxiableUUID on the implementation contract
        // (the implementation itself) is callable (not reverted) after initialization.
        bool ok;
        try c.initialize(accessControl) {
            ok = true; // initialize itself succeeded
        } catch {
            // if initialize reverts, treat as failure to initialize
            ok = false;
        }

        // Now, attempt to call proxiableUUID on c (the implementation). According to UUPS design
        // proxiableUUID is guarded by notDelegated which ensures it is only callable directly on
        // the implementation (not via proxy). The reference's __UUPSUpgradeable_init sets up
        // state so that proxiableUUID can be queried without reverting; the mutant that omits
        // the init will make proxiableUUID revert in some cases. We capture whether it reverts.
        bool proxiableOk;
        try c.proxiableUUID() returns (bytes32) {
            proxiableOk = true;
        } catch {
            proxiableOk = false;
        }

        // General property: for any accessControl input, the correct contract (reference) always
        // leaves proxiableUUID callable (proxiableOk == true) after initialize; the mutant may
        // make proxiableUUID revert for some inputs. We assert proxiableOk is true.
        // This single assertion holds for the reference for all inputs and fails for the mutant
        // for some fuzzed input discovered by the fuzzer.
        assertTrue(proxiableOk);
    }
}

