pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameter: an arbitrary address to act as access control admin during initialization
    function testFuzz_property(address admin) public {
        // Keep domain wide but exclude zero address for meaningful admin
        // zero is still admissible for initializer, so don't assume away too much; only bound to avoid trivial EOA=0 causing no effect
        // we only need to ensure admin is a valid address (including zero is fine), so do not vm.assume(admin != address(0));

        // 1) Call initialize once from the chosen admin (fuzzer supplies admin). Use vm.prank to set msg.sender.
        vm.prank(admin);
        bool okInit;
        try c.initialize(admin) {
            okInit = true;
        } catch {
            okInit = false;
        }

        // If initialize reverted that's allowed for some inputs (e.g., if constructor-like conditions),
        // but when initialize succeeds then the contract should be in a state where calling proxiableUUID() externally
        // on the implementation (this contract) returns the fixed ERC1967 slot constant (i.e., it is callable not-delegated).
        // We observe proxiableUUID by calling it directly; the correct contract implements notDelegated modifier which requires
        // address(this) == __self, so calling proxiableUUID directly should succeed and return ERC1967 slot. The mutant's wrong
        // initialized value can cause different flows around initialization and only the mutant will allow some sequences where
        // this observable deviates. We therefore assert: if initialize succeeded then proxiableUUID() called directly returns
        // ERC1967Utils.IMPLEMENTATION_SLOT (the constant). We cannot import the constant, so we check that the returned slot is non-zero
        // and stable across two direct calls — the reference will always return the same non-zero slot; the mutant can cause one of the calls
        // to revert or return zero in corner cases.

        bytes32 slot1;
        bool okSlotCall1 = false;
        if (okInit) {
            try c.proxiableUUID() returns (bytes32 s) {
                slot1 = s;
                okSlotCall1 = true;
            } catch {
                okSlotCall1 = false;
            }
        }

        // Make a second call to proxiableUUID to check stability
        bytes32 slot2;
        bool okSlotCall2 = false;
        if (okInit) {
            try c.proxiableUUID() returns (bytes32 s2) {
                slot2 = s2;
                okSlotCall2 = true;
            } catch {
                okSlotCall2 = false;
            }
        }

        // Single assertion: if initialize succeeded then both proxiableUUID calls must succeed and return identical non-zero slots.
        // This is a general rule the reference satisfies for every input; the mutant (with altered initializer storing 2) will
        // break this for some admin addresses / call-contexts causing one of the proxiableUUID calls to revert or return differing/zero.
        assertTrue(!okInit || (okSlotCall1 && okSlotCall2 && slot1 != bytes32(0) && slot1 == slot2));
    }
}

