    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameter is the address used as the _accessControl initializer.
    // General rule: for any address a, an external initialize(a) call should succeed once and any immediate
    // subsequent external initialize(a) call should revert (re-initialization is disallowed by the initializer guard).
    // The mutant that sets _initialized = 2 can break this for some addresses (construction-like edge),
    // allowing the second call to succeed; we detect that by calling initialize twice and asserting the second call always reverts.
    function testFuzz_property(address accessControl) public {
        // keep domain wide but avoid zero-address which some implementations might explicitly forbid elsewhere
        // (we keep it wide; allow zero as well to avoid excluding potential buggy behavior)

        bool firstOk;
        bool secondOk;

        // First attempt: must succeed (reference behavior)
        try c.initialize(accessControl) {
            firstOk = true;
        } catch {
            firstOk = false;
        }

        // Second attempt: must revert (reference behavior). We capture whether it succeeds.
        try c.initialize(accessControl) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // Single assertion: reference always has firstOk == true and secondOk == false for every input.
        // This asserts the universal property: initialize succeeds once and a second call reverts.
        assertTrue(firstOk && !secondOk);
    }
}

