import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// Minimal stub Vault to control currentUtilizationIndex and utilization and simulate elapsed time.
contract StubVault {
    uint256 public idx;
    uint256 public util;
    function setIndex(uint256 i) external { idx = i; }
    function setUtil(uint256 u) external { util = u; }
    function currentUtilizationIndex(address) external view returns (uint256) { return idx; }
    function utilization(address) external view returns (uint256) { return util; }
    // unused functions to satisfy IVault interface shape if called elsewhere are omitted for brevity
}

contract InvMutTest is Test {
    C c;
    StubVault vault;

    function setUp() public {
        c = new C();
        vault = new StubVault();
    }

    // Fuzz parameters: prevIndex (previous stored index), newIndex (current index), lastUpdateDelta (seconds since last update)
    // We let the fuzzer choose values; we bound lastUpdateDelta to a reasonable range to avoid overflow in vm.warp arithmetic.
    function testFuzz_property(uint256 prevIndex, uint256 newIndex, uint256 lastUpdateDelta) public {
        // keep elapsed in a wide but reasonable range: 0..1e6 seconds
