import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IVaultMinimal {
    function currentUtilizationIndex(address _asset) external view returns (uint256);
    function utilization(address _asset) external view returns (uint256);
    function currentUtilizationIndexNonView(address _asset) external returns (uint256);
}

// Minimal vault we control to drive indexes/values
contract VaultMock {
    uint256 public idx;
    uint256 public util;
    function set(uint256 _idx, uint256 _util) external {
        idx = _idx;
        util = _util;
    }
    function currentUtilizationIndex(address) external view returns (uint256) { return idx; }
    function utilization(address) external view returns (uint256) { return util; }
    // non-view alias just in case
    function currentUtilizationIndexNonView(address _asset) external returns (uint256) { return currentUtilizationIndex(_asset); }
}

contract InvMutTest is Test {
    C c;
    VaultMock vault;

    function setUp() public {
        c = new C();
        vault = new VaultMock();
    }

    // fuzz parameters: two uint32/uint256 to represent previous index, stored lastUpdate offset and vault values
    function testFuzz_property(uint32 prevIndexLow, uint256 vaultIndex, uint256 vaultUtil) public {
        // Keep domains wide but reasonable
        vm.assume(vaultIndex <= type(uint256).max - 1);
        vm.assume(vaultUtil <= 1e30); // keep utilization in plausible range

        // We will simulate the storage inside C by calling rate twice to establish stored index/lastUpdate,
        // then craft a second call where block.timestamp > lastUpdate but elapsed == 0 due to overflow/wrap considerations.
        // Strategy: set lastUpdate to block.timestamp by first calling rate to initialize storage; then increase block.timestamp
        // and set utilization index so that (index - prevIndex)/elapsed would be valid when elapsed>0. We then arrange elapsed == 0
        // by making lastUpdate == block.timestamp before calling rate — to trigger the branch we want, we will directly manipulate
        // time to create cases where block.timestamp > lastUpdate but elapsed computes to 0: this can happen only if lastUpdate == block.timestamp
        // after the subtraction; to keep this realistic, instead we target the observable behavior: when block.timestamp > lastUpdate and
        // elapsed == 0 the reference falls back to IVault.utilization; we emulate admissible inputs by ensuring block.timestamp > lastUpdate
        // and elapsed==0 via setting lastUpdate to current block.timestamp (so block.timestamp > lastUpdate is false). Since we cannot
        // directly set internal storage of c, we'll instead rely on the universal property: when elapsed==0 the reference uses IVault.utilization.
        // To produce a distinguishing input for the mutant, we fuzz vaultIndex and vaultUtil then call rate and assert the returned value equals
        // the vault-driven computation when elapsed==0 case.

        // Prepare vault behavior
        vault.set(vaultIndex, vaultUtil);

        // Warp time to a known value and perform an initial call to ensure storage exists in c for that vault/asset pair.
        // Use asset address as this test contract for simplicity.
        address asset = address(this);
        address vaultAddr = address(vault);

        // Ensure the first call initializes stored index and lastUpdate to block.timestamp
        vm.warp(1000);
        // call rate once to set lastUpdate/index inside c's storage (this may revert if access control is enforced; assume it isn't for the test harness)
        // We call as this test contract; if Access.checkAccess is enforced, the reference contract would revert — to avoid that, we only assert on the return
        // of a later call. We still call to initialize storage; ignore revert by try/catch.
        try c.rate(vaultAddr, asset) returns (uint256) {
        } catch {
        }

        // Now set vault values so that IVault.utilization(...) returns vaultUtil
        vault.set(vaultIndex, vaultUtil);

        // Now craft a call where elapsed == 0: we want block.timestamp > utilizationData.lastUpdate but computed elapsed == 0.
        // The only way elapsed = block.timestamp - lastUpdate == 0 while block.timestamp > lastUpdate is impossible with uint arithmetic.
        // So instead we target the legitimate reference behavior for elapsed == 0: when elapsed == 0 the reference uses IVault.utilization.
        // We force the scenario by calling rate when block.timestamp == utilizationData.lastUpdate (elapsed == 0) via warp to that timestamp.

        // Warp to the stored lastUpdate value (1000) so elapsed == 0 path is taken and utilization must be read from IVault.utilization
        vm.warp(1000);

        // Now call rate and capture returned latestAnswer
        uint256 latest;
        try c.rate(vaultAddr, asset) returns (uint256 r) {
            latest = r;
        } catch {
            // If the call reverts, the reference must revert consistently; we treat revert as unacceptable for this admissible input,
            // so make the assumption to avoid spurious failures
            revert();
        }

        // The general rule: when elapsed == 0 the contract must use IVault.utilization(asset) as the utilization input;
        // therefore the returned latest value must be exactly _applySlopes(..., utilization=vaultUtil, elapsed=0).
        // We cannot call internal _applySlopes; but we can observe that with elapsed==0 the multiplier updates in _applySlopes
        // perform multiplications/divisions by factors involving _elapsed (zero) so multipliers remain either unchanged or clamped.
        // To create a robust external observable assertion that the reference always satisfies and the mutant violates, we assert
        // that the returned latest equals the value returned when we set vaultIndex=0 and vaultUtil to the same vaultUtil and call rate
        // with identical time (elapsed==0) — because when elapsed==0 the reference ignores index differences and depends only on IVault.utilization.

        // Call rate again after setting vaultIndex to a different number to ensure index difference does not affect the result when elapsed==0
        vault.set(vaultIndex + 12345, vaultUtil);
        vm.warp(1000);
        uint256 latest2;
        try c.rate(vaultAddr, asset) returns (uint256 r2) {
            latest2 = r2;
        } catch {
            revert();
        }

        // Assert the reference returns the same latestAnswer for both calls (since elapsed==0 both should rely only on IVault.utilization)
        assertTrue(latest == latest2);
    }
}

